mapper.select:
SELECT /* QueryID : com.demo.proworks.attendance.selectListAttendanceByTenant */ ar.record_id as recordId, ar.session_id as sessionId, ar.name, ar.email, COALESCE(ar.ip_address, '') as ipAddress, DATE_FORMAT(ar.join_time, '%Y-%m-%d %H:%i:%s') as joinTime, CASE WHEN ar.leave_time IS NOT NULL THEN DATE_FORMAT(ar.leave_time, '%Y-%m-%d %H:%i:%s') ELSE '진행중' END as leaveTime, CASE WHEN ar.leave_time IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, ar.join_time, ar.leave_time) ELSE TIMESTAMPDIFF(MINUTE, ar.join_time, NOW()) END as participationMinutes, CASE WHEN ar.leave_time IS NULL THEN '참여중' ELSE '퇴장완료' END as status FROM ATTENDANCE_RECORD ar INNER JOIN SESSION s ON ar.session_id = s.session_id WHERE s.tenant_id = #{scTenantId}
AND ar.session_id = #{scSessionId}
AND ar.name LIKE CONCAT('%', #{scName}, '%')
AND ar.email LIKE CONCAT('%', #{scEmail}, '%')
AND DATE(ar.join_time) = STR_TO_DATE(#{scJoinTime}, '%Y%m%d')
ORDER BY ar.join_time
ASC
DESC
LIMIT #{startRow}, #{pageSize}

SELECT /* QueryID : com.demo.proworks.attendance.selectListCountAttendanceByTenant */ COUNT(*) FROM ATTENDANCE_RECORD ar INNER JOIN SESSION s ON ar.session_id = s.session_id WHERE s.tenant_id = #{scTenantId}
AND ar.session_id = #{scSessionId}
AND ar.name LIKE CONCAT('%', #{scName}, '%')
AND ar.email LIKE CONCAT('%', #{scEmail}, '%')
AND DATE(ar.join_time) = STR_TO_DATE(#{scJoinTime}, '%Y%m%d')

SELECT /* QueryID : com.demo.proworks.attendance.selectAttendanceForCSVByTenant */ ar.record_id as recordId, ar.session_id as sessionId, ar.name, ar.email, COALESCE(ar.ip_address, '') as ipAddress, DATE_FORMAT(ar.join_time, '%Y-%m-%d %H:%i:%s') as joinTime, CASE WHEN ar.leave_time IS NOT NULL THEN DATE_FORMAT(ar.leave_time, '%Y-%m-%d %H:%i:%s') ELSE '진행중' END as leaveTime, CASE WHEN ar.leave_time IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, ar.join_time, ar.leave_time) ELSE TIMESTAMPDIFF(MINUTE, ar.join_time, NOW()) END as participationMinutes, CASE WHEN ar.leave_time IS NULL THEN '참여중' ELSE '퇴장완료' END as status FROM ATTENDANCE_RECORD ar INNER JOIN SESSION s ON ar.session_id = s.session_id WHERE s.tenant_id = #{scTenantId}
AND ar.session_id = #{scSessionId}
AND ar.name LIKE CONCAT('%', #{scName}, '%')
AND ar.email LIKE CONCAT('%', #{scEmail}, '%')
AND DATE(ar.join_time) = STR_TO_DATE(#{scJoinTime}, '%Y%m%d')
ORDER BY ar.join_time DESC

SELECT /* QueryID : com.demo.proworks.attendance.selectAttendanceStatsByTenant */ COUNT(*) as totalCount, SUM(CASE WHEN ar.leave_time IS NULL THEN 1 ELSE 0 END) as activeCount, SUM(CASE WHEN ar.leave_time IS NOT NULL THEN 1 ELSE 0 END) as leftCount, COALESCE(AVG( CASE WHEN ar.leave_time IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, ar.join_time, ar.leave_time) ELSE TIMESTAMPDIFF(MINUTE, ar.join_time, NOW()) END ), 0) as avgMinutes FROM ATTENDANCE_RECORD ar INNER JOIN SESSION s ON ar.session_id = s.session_id WHERE s.tenant_id = #{scTenantId}
AND ar.session_id = #{scSessionId}
AND ar.name LIKE CONCAT('%', #{scName}, '%')
AND ar.email LIKE CONCAT('%', #{scEmail}, '%')
AND DATE(ar.join_time) = STR_TO_DATE(#{scJoinTime}, '%Y%m%d')

