INSERT INTO ATTENDANCE_RECORD (
RECORD_ID
 , SESSION_ID 
 , NAME       
 , EMAIL      
 , IP_ADDRESS 
 , JOIN_TIME  
 , LEAVE_TIME 
) VALUES (
#{recordId}
 , #{sessionId} 
 , #{name}       
 , #{email}      
 , #{ipAddress} 
 , #{joinTime}  
 , #{leaveTime} 
)

